static inline int hrir_direction_index(int code)
{
    int low = 0, high = HRIR_DIRECTION_COUNT - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (kHrirDirections[mid].code == code) return mid;
        if (kHrirDirections[mid].code < code) low = mid + 1;
        else high = mid - 1;
    }
    return -1;
}
